import CryptoKit
import Foundation
import XCTest
@testable import BridgeyMac

/// protocol/test-vectors/connect-v1.json (generated by the Rust core): the Mac derives the same pair
/// secret, pair check and tunnel transcript. Android (ConnectVectorsTest.kt) and Python check the same file.
final class ConnectVectorsTests: XCTestCase {
    private var vectors: [String: Any] = [:]

    override func setUpWithError() throws {
        let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
            .appendingPathComponent("../../../protocol/test-vectors/connect-v1.json")
        vectors = try XCTUnwrap(JSONSerialization.jsonObject(with: Data(contentsOf: url)) as? [String: Any])
    }

    func testPairSecretFromEitherSide() throws {
        let pair = try XCTUnwrap(vectors["pair"] as? [String: Any])
        let low = try XCTUnwrap(Data(base64Encoded: pair["cLow"] as! String))
        let high = try XCTUnwrap(Data(base64Encoded: pair["cHigh"] as! String))
        let idLow = pair["idLow"] as! String, idHigh = pair["idHigh"] as! String
        let expected = pair["pairSecret"] as! String
        // The lower device holds cLow as its own contribution; the higher holds cHigh. Both reach one secret.
        XCTAssertEqual(ConnectCrypto.pairSecret(local: low, remote: high, localID: idLow, remoteID: idHigh).base64EncodedString(), expected)
        XCTAssertEqual(ConnectCrypto.pairSecret(local: high, remote: low, localID: idHigh, remoteID: idLow).base64EncodedString(), expected)
        let secret = try XCTUnwrap(Data(base64Encoded: expected))
        XCTAssertEqual(ConnectCrypto.pairCheck(secret), pair["pairCheckUrl"] as? String)
        XCTAssertEqual(ConnectCrypto.side(local: idLow, remote: idHigh), 0)
        XCTAssertEqual(ConnectCrypto.side(local: idHigh, remote: idLow), 1)
    }

    func testTunnelTranscript() throws {
        let t = try XCTUnwrap(vectors["transcript"] as? [String: Any])
        let bytes = ConnectCrypto.transcriptV2(
            sessionID: t["sessionId"] as! String, initiator: t["initiatorDeviceId"] as! String, responder: t["responderDeviceId"] as! String,
            initiatorKey: t["initiatorEphemeralKey"] as! String, responderKey: t["responderEphemeralKey"] as! String,
            exporter: t["exporter"] as! String)
        XCTAssertEqual(bytes.base64EncodedString(), t["bytes"] as? String)
    }

    func testUsableAddressesAreLiteralsOnly() {
        for good in ["192.168.1.20", "100.101.1.2", "2409:4040:1:2::20", "fd7a:115c:a1e0::1"] { XCTAssertTrue(isUsableIPLiteral(good), good) }
        for bad in ["127.0.0.1", "::1", "0.0.0.0", "::", "224.0.0.1", "ff02::1", "example.com", "300.1.1.1", "fe80::1%en0", ""] {
            XCTAssertFalse(isUsableIPLiteral(bad), bad)
        }
    }

    func testRouteChips() {
        XCTAssertEqual(connectRouteChipText(tunnelRoute: "relay", relay: "bom", legacy: .unknown), "Relay (Mumbai)")
        XCTAssertEqual(connectRouteChipText(tunnelRoute: "relay", relay: nil, legacy: .unknown), "Relay")
        XCTAssertEqual(connectRouteChipText(tunnelRoute: "vpn", relay: nil, legacy: .unknown), "Private network")
        XCTAssertEqual(connectRouteChipText(tunnelRoute: nil, relay: nil, legacy: .sameNetwork), "Same Wi-Fi")
        XCTAssertNil(connectRouteChipText(tunnelRoute: nil, relay: nil, legacy: .unknown))
        XCTAssertEqual(connectionRoute(forTunnel: "lan"), .sameNetwork)
        XCTAssertEqual(connectionRoute(forTunnel: "relay"), .otherNetwork)
    }

    func testSetupAndAddressesRoundTrip() throws {
        let setup = ConnectSetup(contribution: Data(repeating: 7, count: 32), rotate: true)
        let encoded = try JSONSerialization.data(withJSONObject: setup.payload)
        XCTAssertEqual(ConnectSetup.decode(encoded), setup)
        let addresses = ConnectAddresses(port: 42_458, addrs: [ConnectAddress(a: "192.168.1.20", kind: "lan"),
                                                               ConnectAddress(a: "100.101.1.2", kind: "vpn", vpn: "tailscale")], pairCheck: "r_IQgYZ46wg")
        XCTAssertEqual(ConnectAddresses.decode(try JSONSerialization.data(withJSONObject: addresses.payload)), addresses)
    }

    func testStoreKeepsSecretsAndAddressesPrivately() throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("connect-store-\(UUID().uuidString)")
        defer { try? FileManager.default.removeItem(at: directory) }
        let store = ConnectStore(directory: directory)
        let key = store.nodeKey()
        store.setPairSecret(Data(repeating: 1, count: 32), for: "phone")
        store.learn("phone", port: 42_458, addresses: [ConnectAddress(a: "192.168.1.20", kind: "lan")])
        let reopened = ConnectStore(directory: directory)
        XCTAssertEqual(reopened.nodeKey().rawRepresentation, key.rawRepresentation)
        XCTAssertEqual(reopened.pairSecret("phone"), Data(repeating: 1, count: 32))
        XCTAssertEqual(reopened.addresses("phone").map(\.a), ["192.168.1.20"])
        XCTAssertTrue(reopened.addresses("phone", now: Date().addingTimeInterval(31 * 24 * 3_600)).isEmpty)
        let mode = try FileManager.default.attributesOfItem(atPath: directory.appendingPathComponent(ConnectStore.fileName).path)[.posixPermissions] as? Int
        XCTAssertEqual(mode, 0o600)
        reopened.forget("phone")
        XCTAssertNil(ConnectStore(directory: directory).pairSecret("phone"))
    }

    /// With BRIDGEY_CONNECT_DYLIB set (build-app.sh's copy, or rust/target), the core starts and answers.
    func testCoreStartsWhenTheLibraryIsThere() throws {
        guard let path = ProcessInfo.processInfo.environment["BRIDGEY_CONNECT_DYLIB"], let library = ConnectLibrary(path: path) else {
            throw XCTSkip("Set BRIDGEY_CONNECT_DYLIB to load the core")
        }
        let key = P256.Signing.PrivateKey()
        let reply = library.start(["port": 0, "app": "bridgey-tests", "nodeKey": ConnectCrypto.base64URL(key.publicKey.x963Representation)])
        XCTAssertEqual(reply["ok"] as? Bool, true, "\(reply)")
        let handle = try XCTUnwrap((reply["handle"] as? NSNumber)?.uint64Value)
        let status = library.command(handle, ["c": "status"])
        XCTAssertEqual(status["ok"] as? Bool, true)
        XCTAssertEqual(library.command(handle, ["c": "addresses"])["ok"] as? Bool, true)
        library.stop(handle)
    }

    func testMissingLibraryMeansNotAvailable() {
        XCTAssertNil(ConnectLibrary(path: "/nonexistent/libbridgey_connect.dylib"))
    }
}
